#!/usr/bin/env python3
"""The proxy culls' FL engine reads not already generated by an FL provider, decoded from X3FL.exe (read-only, static).

The small-prop and occlusion culls (cull_small_props_core.h, occlusion_cull_core.h) read, on FL: the scope node's model
+0x144, parent +0x18 and handle +0x28 (object_trace_fl_inc.h, generated by tools/analysis/fl_object_trace_constants.py),
the body manager slot RVA 0x1aa100 (object_trace_fl_inc.h engine_slot_rva, its anchor checked at install), the cockpit
registry slot and layout plus cockpit +0x58 (sector_background_fl_inc.h, anchors checked at admission), cockpit +0xc and
reference +0x70 (verification/results/fl-engine-effects/own_ship_offsets.py). This script decodes the rest at the
native instructions that establish them: the body getter's id -> slot map and table fields, the fixed count 11000,
the selected target cockpit +0x1e0, its object id +8 and its render root +0x70. VAs are at the preferred base 0x400000
(X3FL.exe is relocatable: production adds RVAs to the module base). Prints one JSON line; exit 1 when an anchor does
not decode as expected. docs/reverse-engineering/fl/cull-chain.md, "Proxy culls' engine reads (2026-11-02)".

usage: python3 -I verification/results/fl-proxy-culls/offsets.py [X3FL.exe] > verification/results/fl-proxy-culls/offsets.json
"""
import hashlib
import json
import struct
import sys

import capstone

EXE = sys.argv[1] if len(sys.argv) > 1 else '/mnt/c/X3FL/X3FL.exe'
# (VA, mnemonic, memory displacement or None, immediate or None, role)
ANCHORS = [
    (0x4867c1, 'mov', 0x5aa100, None, 'body getter loads the manager from the engine slot (RVA 0x1aa100)'),
    (0x4867c7, 'cmp', None, 1000, 'id < 1000: slot = id'),
    (0x4867d3, 'cmp', None, 20000, 'id < 20000: slot = id - 9000'),
    (0x4867db, 'lea', -9000, None, 'slot = id - 9000'),
    (0x4867e3, 'lea', -20000, None, 'dynamic: slot = id - 20000 ...'),
    (0x4867e9, 'add', 0xb4, None, '... + fixed count manager+0xb4'),
    (0x4867f3, 'mov', 0xb8, None, 'bound: dynamic count manager+0xb8'),
    (0x4867f9, 'add', 0xb4, None, 'bound: + fixed count'),
    (0x486803, 'mov', 0xbc, None, 'slot array manager+0xbc'),
    (0x486809, 'lea', 0, None, 'slot * 8 ...'),
    (0x486810, 'sub', None, None, '... - slot = slot * 7 dwords (stride 0x1c)'),
    (0x486812, 'mov', 0xc, None, 'name pointer slot+0xc (index scale 4)'),
    (0x48a5f7, 'mov', 0xb4, 11000, 'factory sets the fixed count 11000'),
    (0x43106f, 'mov', 0x1e0, None, 'target command reads the selected target cockpit+0x1e0'),
    (0x43107d, 'push', 0x8, None, 'and exports its object id target+8'),
    (0x4275ed, 'mov', 0x1e0, None, 'target setter stores cockpit+0x1e0'),
    (0x427672, 'cmp', 0x1e0, None, 'target invalidator compares cockpit+0x1e0'),
    (0x42767a, 'mov', 0x1e0, 0, 'and clears it'),
    (0x4506d8, 'mov', 0x70, None, 'solver loads the target render root target+0x70'),
]


def main():
    data = open(EXE, 'rb').read()
    pe = struct.unpack_from('<I', data, 0x3c)[0]
    count = struct.unpack_from('<H', data, pe + 6)[0]
    optional = struct.unpack_from('<H', data, pe + 20)[0]
    sections = [struct.unpack_from('<8sIIII', data, pe + 24 + optional + 40 * i) for i in range(count)]

    def at(rva, n):
        for _, vsize, va, rsize, raw in sections:
            if va <= rva < va + vsize:
                return data[raw + rva - va:raw + rva - va + n]
        raise ValueError(hex(rva))

    md = capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_32)
    md.detail = True
    rows, ok = [], True
    for va, mnemonic, disp, imm, role in ANCHORS:
        insn = next(md.disasm(at(va - 0x400000, 16), va))
        mems = [op.mem for op in insn.operands if op.type == capstone.x86.X86_OP_MEM]
        imms = [op.imm for op in insn.operands if op.type == capstone.x86.X86_OP_IMM]
        good = insn.mnemonic == mnemonic and (disp is None or any(m.disp == disp for m in mems)) and \
            (imm is None or imm in imms)
        if va == 0x486812:
            good &= any(m.scale == 4 for m in mems)
        if va == 0x486810:
            good &= insn.op_str == 'ecx, esi'
        if va == 0x486809:
            good &= any(m.scale == 8 for m in mems)
        ok &= good
        rows.append(dict(va=hex(va), rva=hex(va - 0x400000), text=f'{insn.mnemonic} {insn.op_str}', ok=good, role=role))
    print(json.dumps(dict(exe=EXE, sha256=hashlib.sha256(data).hexdigest(), anchors=rows, passed=ok)))
    return 0 if ok else 1


if __name__ == '__main__':
    sys.exit(main())
